contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address target) internal {
        target = address(this);
        bool ok1;
        try c.setOwner(target) returns (bool __r) { ok1 = __r; } catch { return; }
        address before;
        try c.owner() returns (address __r) { before = __r; } catch { return; }
        bool ok2;
        try c.setOwner(target) returns (bool __r) { ok2 = __r; } catch { return; }
        assertTrue(ok1 && ok2 && before == address(this) && c.owner() == address(this));
    }

    function testFuzz_run(address target) public {
        _run(target);
    }

    receive() external payable {}
}
